const assert = require('node:assert/strict');
const { Ledger } = require('../.build/ledger');
const { PaymentService } = require('../.build/service');
const { Transient } = require('../.build/transport');

async function main() {
  // Repeated equal amount returns the original receipt; no duplicate debit.
  const ledger = new Ledger();
  let acks = 0;
  const service = new PaymentService(ledger, {
    acknowledge: async r => { acks++; if (acks <= 2) throw new Transient('flaky'); },
  });
  const first = await service.pay('shop', 'sale', 123);
  const again = await service.pay('shop', 'sale', 123);
  assert.equal(again, first, 'must return the original receipt');
  assert.equal(ledger.entries.length, 1, 'no duplicate debit');

  // Concurrent equal calls commit exactly one debit and share one receipt.
  const ledger2 = new Ledger();
  const [a, b] = await Promise.all([
    ledger2.apply('shop', 'sale', 99),
    ledger2.apply('shop', 'sale', 99),
  ]);
  assert.equal(a, b);
  assert.equal(ledger2.entries.length, 1);

  // Key reuse with a different amount: key conflict, no extra debit.
  await assert.rejects(service.pay('shop', 'sale', 456), /key conflict/);
  assert.equal(ledger.entries.length, 1, 'conflict must not debit');
  assert.equal(acks, 4, 'conflict must not reach the transport');

  // Transient retried up to `attempts` total tries; same receipt each time.
  const seen = [];
  const ledger3 = new Ledger();
  let tries = 0;
  const flaky = new PaymentService(ledger3, {
    acknowledge: async r => { seen.push(r); tries++; if (tries < 3) throw new Transient('again'); },
  });
  await flaky.pay('t', 'k', 10, 3);
  assert.equal(tries, 3);
  assert.equal(ledger3.entries.length, 1);
  assert.ok(seen.every(r => r === seen[0]), 'same receipt forwarded each retry');

  // Exhausted retries preserve the final exception.
  const ledger4 = new Ledger();
  let n = 0;
  const dead = new PaymentService(ledger4, {
    acknowledge: async () => { n++; throw new Transient('boom-' + n); },
  });
  await assert.rejects(dead.pay('t', 'k', 5, 2), /boom-2/);
  assert.equal(n, 2);
  assert.equal(ledger4.entries.length, 1, 'exactly one debit despite failed acks');

  // Non-Transient errors are not retried.
  let once = 0;
  const strict = new PaymentService(new Ledger(), {
    acknowledge: async () => { once++; throw new Error('hard'); },
  });
  await assert.rejects(strict.pay('t', 'k', 5), /hard/);
  assert.equal(once, 1);

  // Validation before any ledger or transport action.
  const ledger5 = new Ledger();
  let touched = 0;
  const svc = new PaymentService(ledger5, { acknowledge: async () => { touched++; } });
  for (const args of [
    ['', 'k', 5, 3], ['t', '', 5, 3], ['t', 'k', 0, 3], ['t', 'k', 1.5, 3],
    ['t', 'k', 5, 0], ['t', 'k', 5, 6], ['t', 'k', 5, 2.5],
  ]) {
    await assert.rejects(svc.pay(...args), /invalid payment/);
  }
  assert.equal(ledger5.entries.length, 0);
  assert.equal(touched, 0);
}

module.exports = main();

