import { Ledger, Receipt } from './ledger';
import { Transient, Transport } from './transport';
export class PaymentService {
  constructor(private readonly ledger: Ledger, private readonly transport: Transport) {}
  async pay(tenant: string, key: string, cents: number, attempts = 3): Promise<Receipt> {
    // Validate everything before touching the ledger or the transport.
    if (typeof tenant !== 'string' || tenant.length === 0) throw new Error('invalid payment');
    if (typeof key !== 'string' || key.length === 0) throw new Error('invalid payment');
    if (!Number.isInteger(cents) || cents <= 0) throw new Error('invalid payment');
    if (!Number.isInteger(attempts) || attempts < 1 || attempts > 5) throw new Error('invalid payment');
    let lastError: unknown;
    for (let n = 0; n < attempts; n++) {
      try {
        // Ledger.apply is idempotent per (tenant, key): a retry re-debits
        // nothing and hands back the original receipt, so the transport is
        // acknowledged with the same receipt every time.
        const receipt = await this.ledger.apply(tenant, key, cents);
        await this.transport.acknowledge(receipt);
        return receipt;
      } catch (error) {
        lastError = error;
        if (!(error instanceof Transient)) throw error;
      }
    }
    // Retries exhausted: preserve the final thrown exception.
    throw lastError;
  }
}
